 range(tableQuery_,tableTime_);range(mapQuery_,mapTime_);tableQuery_.since=std::max(tableQuery_.since,tableCleared_);mapQuery_.since=std::max(mapQuery_.since,mapCleared_);tableQuery_.firstSince=tableCleared_;mapQuery_.firstSince=mapCleared_;engine_->query(tableQuery_,mapQuery_,++generation_);lastRefresh_=ImGui::GetTime();
